import pandas as pd

LINK_PREFIXES = ("http://", "https://")


def transform(row):
    record_id = row["record_id"]
    link = _present(row["lobbying_source_url"])
    if link is None or not link.startswith(LINK_PREFIXES):
        raise StepRefused(
            f"record {record_id} gives {row['lobbying_source_url']!r} as the source of "
            f"what it asked for, which is not an http or https address — a claim nobody "
            f"can open is a claim nobody can check, and it does not enter this workflow"
        )
    if _present(row["lobbying_issue"]) is None:
        raise StepRefused(
            f"record {record_id} says nothing about what this organisation asked "
            f"government for, so there is no ask to weigh against its public promise"
        )
    if _present(row["lobbying_source_date"]) is None:
        raise StepRefused(
            f"record {record_id} says nothing about when its source was published or "
            f"read, so nobody reading the report can tell how old the ask is"
        )
    return {**row, "lobbying_source_url": link}


def _present(value):
    if value is None or bool(pd.isna(value)):
        return None
    text = str(value).strip()
    return text or None

