import html as _html
import pathlib

import pandas as pd

# The page's markup, in the stage that writes it. A publish stage emits a document, so
# its markup is part of what the stage IS — a reader reviewing this step reads it here
# rather than chasing a file the workflow does not carry.
DOCUMENT = """\
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Tutorial Say versus Do</title>
<style>
  body { font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
         margin: 2rem auto; max-width: 1180px; padding: 0 1rem; line-height: 1.45; }
  h1 { font-size: 1.45rem; margin-bottom: .2rem; }
  p { margin: .5rem 0; }
  .sub, .note, .muted, .src { font-size: .85rem;
        color: color-mix(in srgb, currentColor 60%, transparent); }
  .note, .why { border-left: 3px solid color-mix(in srgb, currentColor 30%, transparent);
        padding: .1rem 0 .1rem .8rem; margin: 1rem 0; }
  .why { font-size: .9rem; max-width: 62ch; }
  table { border-collapse: collapse; width: 100%; font-size: .88rem; margin-top: 1.4rem; }
  th, td { text-align: left; padding: .5rem .6rem; vertical-align: top;
           border-bottom: 1px solid color-mix(in srgb, currentColor 15%, transparent); }
  th { font-size: .7rem; text-transform: uppercase; letter-spacing: .05em;
       border-bottom-width: 2px; }
  tr.flagged td:first-child { border-left: 3px solid currentColor; }
  .pill { border: 1px solid color-mix(in srgb, currentColor 30%, transparent);
          border-radius: 999px; padding: .05rem .5rem; font-size: .78rem;
          white-space: nowrap; }
  .none { color: color-mix(in srgb, currentColor 40%, transparent); font-style: italic; }
  .src { display: block; margin-top: .25rem; }
  .said, .asked { max-width: 44ch; }
  .reviewed { margin: .4rem 0 0; font-size: .8rem; max-width: 40ch; }
  .quote { margin: .4rem 0 0; font-size: .82rem; max-width: 40ch; }
  .label { font-weight: 700; text-transform: uppercase; letter-spacing: .04em;
           font-size: .7rem; display: block; }
</style>
</head>
<body>
<h1>Tutorial Say versus Do</h1>
<p class="sub">[[record_count]] advocacy records; [[flagged_count]] carry an ask a named reviewer decided cannot be squared with the organisation's own public commitment; [[unmatched_count]] have no public commitment on record.</p>
<p class="why">Every promise and every ask on this page was read off a published page, and every
one links to it &mdash; the link is the point, and a reader who does not believe a row can open
both sides of it. A model proposed how each pair stands; every contradiction it proposed went to a
person, who kept or changed the label. What is printed is the person's answer, named and dated
&mdash; the model's is kept beside it in the run. This page makes no accusation of its own: it puts
two sourced texts side by side and says who decided how they stand. A reading aid, not a verdict.
Every row carries a <em>Show the work</em> link back through each stage to the record it came from.</p>
<table>
<thead><tr>
<th>Record</th><th>Organisation</th><th>Period</th>
<th>What they said in public</th><th>What they asked government for</th>
<th>Where the judgement stands</th><th>Show the work</th>
</tr></thead>
<tbody>
[[rows]]</tbody>
</table>
</body>
</html>
"""

ROW = """\
<tr class="[[row_class]]">
<td>[[record_id]]</td>
<td>[[organisation]]</td>
<td class="muted">[[period]]</td>
<td class="said">[[commitment]]</td>
<td class="asked">[[ask]]</td>
<td>[[judgement]]</td>
<td>[[trace]]</td>
</tr>
"""

TRACE = """\
<a href="[[trace_url]]">Lineage</a>
"""

SOURCED = """\
[[text]]<span class="src"><a href="[[source_url]]">source</a></span>
"""

NO_COMMITMENT = """\
<span class="none">No public commitment on record</span>
"""

JUDGEMENT = """\
<span class="pill">[[reviewed_judgment]]</span>
"""

REVIEW = """\
<p class="reviewed"><span class="label">[[headline]]</span>[[reviewer]], [[reviewed_at]]</p>
[[note]]
"""

REVIEW_NOTE = """\
<p class="quote">[[review_notes]]</p>
"""

SECTIONS = {
    "document": DOCUMENT, "row": ROW, "trace": TRACE, "sourced": SOURCED,
    "no_commitment": NO_COMMITMENT, "judgement": JUDGEMENT, "review": REVIEW,
    "review_note": REVIEW_NOTE,
}
TOKEN_OPEN = "[["


# The ordinal a trace URL needs is a position in THIS frame, so the stage it names is
# this step's own input, and the rows are rendered in the order they arrived.
TRACED_INPUT = "review_contradictions"
CONTRADICTS = "Contradicts"
NOT_REVIEWED = "skipped"
KEPT = "approve"


def transform(df, output_dir, citation_provider):
    sections = SECTIONS
    page = _fill(
        sections["document"],
        record_count=str(len(df)),
        flagged_count=str(sum(_contradicts(row) for _, row in df.iterrows())),
        unmatched_count=str(int(df["public_commitment"].isna().sum())),
        rows="".join(
            _render_row(sections, row, citation_provider, ordinal)
            for ordinal, (_, row) in enumerate(df.iterrows())
        ),
    )
    out_path = pathlib.Path(output_dir) / "tutorial_say_versus_do_report.html"
    out_path.write_text(page, encoding="utf-8")
    return pd.DataFrame([{"report_path": str(out_path), "record_count": len(df)}])


def _render_row(sections, row, citation_provider, ordinal):
    return _fill(
        sections["row"],
        row_class="flagged" if _contradicts(row) else "",
        record_id=_escaped(row["record_id"]),
        organisation=_escaped(row["organisation"]),
        period=_escaped(row["period"]),
        commitment=_render_commitment(sections, row),
        ask=_fill(
            sections["sourced"],
            text=_escaped(row["lobbying_issue"]),
            source_url=_escaped(row["lobbying_source_url"]),
        ),
        judgement=_render_judgement(sections, row),
        trace=_fill(
            sections["trace"],
            trace_url=_escaped(citation_provider.cite_row(TRACED_INPUT, ordinal)),
        ),
    )


def _render_commitment(sections, row):
    said = _present(row["public_commitment"])
    link = _present(row["commitment_source_url"])
    if said is None:
        return sections["no_commitment"]
    if link is None:
        raise StepRefused(
            f"record {row['record_id']} carries a public commitment with no link to "
            f"where it was said, so this page would print a claim nobody can check"
        )
    return _fill(sections["sourced"], text=_escaped(said), source_url=_escaped(link))


def _render_judgement(sections, row):
    label = _reviewed_judgment(row)
    if label == CONTRADICTS and _present(row["public_commitment"]) is None:
        raise StepRefused(
            f"record {row['record_id']} is judged to contradict a public commitment, "
            f"yet none was matched onto it, so this report cannot say what it "
            f"contradicts"
        )
    return _fill(sections["judgement"], reviewed_judgment=_escaped(label)) + _render_review(
        sections, row)


def _render_review(sections, row):
    verdict = _present(row["review_verdict"])
    if verdict == NOT_REVIEWED:
        return ""
    reviewer = _present(row["reviewer"])
    reviewed_at = _present(row["reviewed_at"])
    if reviewer is None or reviewed_at is None:
        raise StepRefused(
            f"record {row['record_id']} carries a reviewed judgment with no reviewer "
            f"or time recorded against it, so this report cannot say who reviewed it or "
            f"when — an unreviewed judgment is the model's, and is not published as a "
            f"person's"
        )
    return _fill(
        sections["review"],
        headline=(
            "Confirmed by" if verdict == KEPT
            else "Changed from " + _escaped(row["ai_judgment"]) + " by"
        ),
        reviewer=_escaped(reviewer),
        reviewed_at=_escaped(reviewed_at),
        note=_render_note(sections, row),
    )


def _render_note(sections, row):
    note = _present(row["review_notes"])
    if note is None:
        return ""
    return _fill(sections["review_note"], review_notes=_escaped(note))


def _contradicts(row):
    return _reviewed_judgment(row) == CONTRADICTS


def _reviewed_judgment(row):
    # The published label is the reviewer's, so a row without one is not publishable.
    label = _present(row["reviewed_judgment"])
    if label is None:
        raise StepRefused(
            f"record {row['record_id']} reaches the report with no judgment on it at "
            f"all, neither the model's nor a reviewer's, so there is nothing to print"
        )
    return label


def _fill(template, **values):
    filled = template
    for name, value in values.items():
        filled = filled.replace(TOKEN_OPEN + name + "]]", value)
    if TOKEN_OPEN in filled:
        raise ValueError(
            "the report markup has a placeholder this step does not fill"
        )
    return filled


def _escaped(value):
    return _html.escape(str(value))


def _present(value):
    if value is None or bool(pd.isna(value)):
        return None
    return str(value)
